import re
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    if horizon is None:
        horizon = 1200.0
    if start is None:
        start = 0.0

    # 1. Parse Inputs
    machines_info = {}
    tasks_info = {}
    for inp in inputs:
        if inp['kind'] == 'machine_config':
            mid = inp['entities'][0]
            machines_info[mid] = {
                'cpu': inp['fields']['cpu'],
                'mem': inp['fields']['memory'],
                'fails_at': inp['fields']['fails_at'],
                'returns_at': inp['fields']['returns_at'],
            }
        elif inp['kind'] == 'task_submission':
            tid = inp['entities'][0]
            tasks_info[tid] = {
                'job': inp['fields']['job'],
                'priority': inp['fields']['priority'],
                'cpu': inp['fields']['cpu'],
                'mem': inp['fields']['memory'],
                'run_time': inp['fields']['run_time'],
                'submit_time': float(inp['time']),
                'id': tid
            }

    # State variables
    m_state = {mid: {
        'up': True,
        'running': {}, # tid: start_time
    } for mid in machines_info}

    m_ids = sorted(machines_info.keys())
    t_state = {tid: {
        'state': 'waiting', 
        'start_time': None, 
        'machine': None, 
        'first_start': None
    } for tid in tasks_info}

    queue = [] # List of tid
    outcomes = []

    def get_resources(mid, t, round_starts=None):
        res_cpu = machines_info[mid]['cpu']
        res_mem = machines_info[mid]['memory']
        for tid, start_t in m_state[mid]['running'].items():
            if start_t + tasks_info[tid]['run_time'] > t:
                res_cpu -= tasks_info[tid]['cpu']
                res_mem -= tasks_info[tid]['mem']
        if round_starts:
            for tid, start_t in round_starts.items():
                if start_t + tasks_info[tid]['run_time'] > t:
                    res_cpu -= tasks_info[tid]['cpu']
                    res_mem -= tasks_info[tid]['mem']
        return res_cpu, res_mem

    def get_earliest_start(mid, t_now, tid):
        req_cpu = tasks_info[tid]['cpu']
        req_mem = tasks_info[tid]['mem']
        if req_cpu > machines_info[mid]['cpu'] or req_mem > machines_info[mid]['memory']:
            return None

        possible_times = {t_now}
        for tid_run, start_t in m_state[mid]['running'].items():
            finish_t = start_t + tasks_info[tid_run]['run_time']
            if finish_t >= t_now:
                possible_times.add(finish_t)

        for t in sorted(list(possible_times)):
            cur_cpu, cur_mem = get_resources(mid, t)
            if cur_cpu >= req_cpu and cur_mem >= req_mem:
                return t
        return None

    t = 0.0
    while t <= horizon:
        event_times = set()
        for mid in m_ids:
            for tid, start_t in m_state[mid]['running'].items():
                ft = start_t + tasks_info[tid]['run_time']
                if ft > t: event_times.add(ft)
            if machines_info[mid]['fails_at'] and machines_info[mid]['fails_at'] > t:
                event_times.add(machines_info[mid]['fails_at'])
            if machines_info[mid]['returns_at'] and machines_info[mid]['returns_at'] > t:
                event_times.add(machines_info[mid]['returns_at'])
        for tid, info in tasks_info.items():
            if info['submit_time'] > t:
                event_times.add(info['submit_time'])

        if not event_times:
            break
        t_next = min(event_times)
        if t_next > horizon:
            t_next = horizon
        t = t_next

        # 1. Finishes
        finishing = []
        for mid in m_ids:
            for tid, start_t in list(m_state[mid]['running'].items()):
                if start_t + tasks_info[tid]['run_time'] == t:
                    finishing.append((tid, mid))
        for tid, mid in sorted(finishing):
            del m_state[mid]['running'][tid]
            t_state[tid]['state'] = 'finished'
            if t > start:
                outcomes.append({"time": t, "kind": "task_finish", "entities": [tid, mid], "value": None})

        # 2. Failures
        failing_machines = sorted([mid for mid in m_ids if machines_info[mid]['fails_at'] == t])
        for mid in failing_machines:
            m_state[mid]['up'] = False
            failed_tasks = sorted(list(m_state[mid]['running'].keys()))
            for tid in failed_tasks:
                del m_state[mid]['running'][tid]
                t_state[tid]['state'] = 'waiting'
                t_state[tid]['machine'] = None
                queue.append(tid)
                if t > start:
                    outcomes.append({"time": t, "kind": "task_fail", "entities": [tid, mid], "value": None})

        # 3. Returns
        returning_machines = sorted([mid for mid in m_ids if machines_info[mid]['returns_at'] == t])
        for mid in returning_machines:
            m_state[mid]['up'] = True
            m_state[mid]['running'] = {}

        # 4. Submissions
        submitted_tasks = sorted([tid for tid, info in tasks_info.items() if info['submit_time'] == t])
        for tid in submitted_tasks:
            queue.append(tid)
            t_state[tid]['state'] = 'waiting'

        # 5. Scheduling round
        queue.sort(key=lambda tid: (-tasks_info[tid]['priority'], tasks_info[tid]['submit_time'], tid))

        reservation = None
        round_starts_per_m = {mid: {} for mid in m_ids}

        idx = 0
        while idx < len(queue):
            tid = queue[idx]
            idx += 1

            started = False
            # a. First fit
            for mid in m_ids:
                if not m_state[mid]['up']: continue
                cpu_av, mem_av = get_resources(mid, t, round_starts_per_m[mid])
                if reservation is None:
                    if cpu_av >= tasks_info[tid]['cpu'] and mem_av >= tasks_info[tid]['mem']:
                        m_state[mid]['running'][tid] = t
                        round_starts_per_m[mid][tid] = t
                        t_state[tid]['state'] = 'running'
                        t_state[tid]['machine'] = mid
                        t_state[tid]['start_time'] = t
                        if t_state[tid]['first_start'] is None: t_state[tid]['first_start'] = t
                        if t > start:
                            outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                        started = True
                        break
                else:
                    m_res, t_res, tid_res = reservation
                    if mid != m_res:
                        if cpu_av >= tasks_info[tid]['cpu'] and mem_av >= tasks_info[tid]['mem']:
                            m_state[mid]['running'][tid] = t
                            round_starts_per_m[mid][tid] = t
                            t_state[tid]['state'] = 'running'
                            t_state[tid]['machine'] = mid
                            t_state[tid]['start_time'] = t
                            if t_state[tid]['first_start'] is None: t_state[tid]['first_start'] = t
                            if t > start:
                                outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                            started = True
                            break
                    else:
                        rt = tasks_info[tid]['run_time']
                        req_cpu = tasks_info[tid]['cpu']
                        req_mem = tasks_info[tid]['mem']
                        fit_all = True
                        check_times = {t}
                        for tid_r, st in m_state[mid]['running'].items(): check_times.add(st + tasks_info[tid_r]['run_time'])
                        for tid_r, st in round_starts_per_m[mid].items(): check_times.add(st + tasks_info[tid_r]['run_time'])
                        for ct in sorted([ct for ct in check_times if t <= ct < t + rt]):
                            c_av, m_av = get_resources(mid, ct, round_starts_per_m[mid])
                            if c_av < req_cpu or m_av < req_mem:
                                fit_all = False; break
                        if fit_all:
                            if t + rt > t_res:
                                c_res_t, m_res_t = get_resources(mid, t_res, round_starts_per_m[mid])
                                if c_res_t < req_cpu + tasks_info[tid_res]['cpu'] or m_res_t < req_mem + tasks_info[tid_res]['mem']:
                                    fit_all = False
                        if fit_all:
                            m_state[mid]['running'][tid] = t
                            round_starts_per_m[mid][tid] = t
                            t_state[tid]['state'] = 'running'
                            t_state[tid]['machine'] = mid
                            t_state[tid]['start_time'] = t
                            if t_state[tid]['first_start'] is None: t_state[tid]['first_start'] = t
                            if t > start:
                                outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                            started = True
                            break
            if started: continue

            # b. Preemption
            if reservation is None and tasks_info[tid]['priority'] >= 9:
                for mid in m_ids:
                    if not m_state[mid]['up']: continue
                    free_tasks = [ft for ft in m_state[mid]['running'] if tasks_info[ft]['priority'] <= 1]
                    free_tasks.sort(key=lambda x: (tasks_info[x]['priority'], -m_state[mid]['running'][x], -int(x[1:])))

                    evicted_this_m = []
                    current_cpu, current_mem = get_resources(mid, t)
                    for ftid in free_tasks:
                        if current_cpu >= tasks_info[tid]['cpu'] and current_mem >= tasks_info[tid]['mem']:
                            break
                        current_cpu += tasks_info[ftid]['cpu']
                        current_mem += tasks_info[ftid]['mem']
                        evicted_this_m.append(ftid)

                    if current_cpu >= tasks_info[tid]['cpu'] and current_mem >= tasks_info[tid]['mem']:
                        for ftid in evicted_this_m:
                            del m_state[mid]['running'][ftid]
                            t_state[ftid]['state'] = 'waiting'
                            t_state[ftid]['machine'] = None
                            queue.append(ftid) 
                            if t > start:
                                outcomes.append({"time": t, "kind": "task_evict", "entities": [ftid, mid], "value": None})
                        m_state[mid]['running'][tid] = t
                        t_state[tid]['state'] = 'running'
                        t_state[tid]['machine'] = mid
                        t_state[tid]['start_time'] = t
                        if t_state[tid]['first_start'] is None: t_state[tid]['first_start'] = t
                        if t > start:
                            outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                        started = True
                        break
            if started: continue

            # c. Reservation
            if reservation is None:
                best_t_res = float('inf')
                best_mid = None
                for mid in m_ids:
                    if not m_state[mid]['up']: continue
                    t_res = get_earliest_start(mid, t, tid)
                    if t_res is not None and t_res < best_t_res:
                        best_t_res = t_res
                        best_mid = mid
                if best_mid is not None:
                    reservation = (best_mid, best_t_res, tid)
                else:
                    continue

        queue = [tid for tid in queue if t_state[tid]['state'] == 'waiting']

    return outcomes

import re

def node_by_title(doc, title):
    for node in doc['nodes']:
        if node['title'] == title:
            return node
    return None

def node_by_id(doc, node_id):
    for node in doc['nodes']:
        if node['node_id'] == node_id:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get('children', [])]

def scope_nodes(doc, scope_title):
    node = node_by_title(doc, scope_title)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if node['kind'] != 'table':
        return []
    cols = node['table']['columns']
    rows = node['table']['rows']
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope) -> list:
    nodes = scope_nodes(doc, scope)
    ents = []

    # Machines
    m_node = next((n for n in nodes if n['title'] == f"{scope}: Machines"), None)
    if m_node:
        for _, row in table_rows(m_node):
            mid = row['machine']
            ents.append({"id": mid, "description": f"Machine {mid}"})

    # Tasks
    t_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if t_node:
        tasks = set()
        for _, row in table_rows(t_node):
            tasks.add(row['task'])
        for tid in sorted(list(tasks)):
            ents.append({"id": tid, "description": f"Task {tid}"})

    return ents

def recorded_end(doc, scope) -> float:
    return 1200.0

def inputs(doc, scope) -> list:
    nodes = scope_nodes(doc, scope)
    inputs_list = []

    # Machine Configurations
    m_node = next((n for n in nodes if n['title'] == f"{scope}: Machines"), None)
    if m_node:
        for i, row in table_rows(m_node):
            mid = row['machine']
            def parse_time(val):
                if val == '-' or val == 'never':
                    return None
                try:
                    return float(val)
                except (ValueError, TypeError):
                    return None

            inputs_list.append({
                "id": f"input_machine_{mid}",
                "time": 0.0,
                "kind": "machine_config",
                "entities": [mid],
                "fields": {
                    "cpu": int(row['CPU']),
                    "memory": int(row['memory']),
                    "fails_at": parse_time(row['fails at']),
                    "returns_at": parse_time(row['returns at'])
                },
                "src": [[m_node['node_id'], i]]
            })

    # Task Submissions
    t_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if t_node:
        for i, row in table_rows(t_node):
            if row['event'] == 'submit':
                tid = row['task']
                inputs_list.append({
                    "id": f"input_submit_{tid}",
                    "time": float(row['time']),
                    "kind": "task_submission",
                    "entities": [tid],
                    "fields": {
                        "job": row['job'],
                        "priority": int(row['priority']),
                        "cpu": int(row['CPU']),
                        "memory": int(row['memory']),
                        "run_time": int(row['run time'])
                    },
                    "src": [[t_node['node_id'], i]]
                })

    return inputs_list

def outcomes(doc, scope) -> list:
    nodes = scope_nodes(doc, scope)
    outcomes_list = []

    # Task Log Events
    t_node = next((n for n in nodes if n['title'] == f"{scope}: Task log"), None)
    if t_node:
        for i, row in table_rows(t_node):
            event = row['event']
            if event in ['start', 'finish', 'evict', 'fail']:
                tid = row['task']
                ents = [tid]
                if row['machine'] != '-':
                    ents.append(row['machine'])

                outcomes_list.append({
                    "time": float(row['time']),
                    "kind": f"task_{event}",
                    "entities": ents,
                    "value": None,
                    "src": [[t_node['node_id'], i]]
                })

    # Final state: Running
    run_node = next((n for n in nodes if "Queue at window end: Tasks running" in n['title']), None)
    if run_node:
        for i, row in table_rows(run_node):
            tid = row['task']
            mid = row['machine']
            outcomes_list.append({
                "time": 1200.0,
                "kind": "final_state_running",
                "entities": [tid, mid],
                "value": float(row['remaining']),
                "src": [[run_node['node_id'], i]]
            })

    # Final state: Waiting
    wait_node = next((n for n in nodes if "Queue at window end: Tasks waiting" in n['title']), None)
    if wait_node:
        for i, row in table_rows(wait_node):
            tid = row['task']
            outcomes_list.append({
                "time": 1200.0,
                "kind": "final_state_waiting",
                "entities": [tid],
                "value": None,
                "src": [[wait_node['node_id'], i]]
            })

    # Wait times from Events list
    e_node = next((n for n in nodes if n['title'] == f"{scope}: Events"), None)
    if e_node and e_node['kind'] == 'list':
        for i, line in enumerate(e_node['lines']):
            wait_match = re.search(r'The longest wait was (\d+) seconds \(task (T\d+)\)', line)
            if wait_match:
                outcomes_list.append({
                    "time": 1200.0,
                    "kind": "longest_wait",
                    "entities": [wait_match.group(2)],
                    "value": float(wait_match.group(1)),
                    "src": [[e_node['node_id'], i]]
                })

    return outcomes_list

def params(doc, scope) -> dict:
    return {"window_length": 1200}



