import collections
import heapq

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    if horizon is None:
        horizon = 1200.0
    if start is None:
        start = 0.0

    # Extract inputs
    machines_cfg = {}
    submissions = []
    for inp in inputs:
        if inp['kind'] == 'machine_config':
            mid = inp['entities'][0]
            machines_cfg[mid] = inp['fields']
        elif inp['kind'] == 'task_submission':
            tid = inp['entities'][0]
            submissions.append({
                'id': tid,
                'time': inp['time'],
                'job': inp['fields']['job'],
                'priority': inp['fields']['priority'],
                'cpu': inp['fields']['cpu'],
                'memory': inp['fields']['memory'],
                'run_time': inp['fields']['run_time']
            })

    # Machine order
    machine_ids = sorted(machines_cfg.keys())

    # State
    # machine_state[mid] = {'up': bool, 'cpu_used': int, 'mem_used': int, 'tasks': {tid: start_time}}
    machine_state = {mid: {'up': True, 'cpu_used': 0, 'mem_used': 0, 'tasks': {}} for mid in machine_ids}
    tasks_info = {}
    queue = []
    running_tasks = {} # tid -> {'mid': mid, 'start_time': t, 'run_time': r}
    task_meta = {} # tid -> {'submitted': t, 'priority': p}
    outcomes_all = []

    # Process every second from 0 up to horizon
    for current_time in range(int(horizon) + 1):
        t = float(current_time)

        # 1. Finishes
        # Tasks whose run time is over finish and free their CPU and memory.
        finished_this_tick = []
        for tid, run_data in list(running_tasks.items()):
            if run_data['start_time'] + run_data['run_time'] == t:
                mid = run_data['mid']
                finished_this_tick.append((tid, mid))

        # Finish events follow tid order
        finished_this_tick.sort(key=lambda x: x[0])
        for tid, mid in finished_this_tick:
            machine_state[mid]['cpu_used'] -= tasks_info[tid]['cpu']
            machine_state[mid]['mem_used'] -= tasks_info[tid]['memory']
            if tid in machine_state[mid]['tasks']:
                del machine_state[mid]['tasks'][tid]
            del running_tasks[tid]
            outcomes_all.append({'time': t, 'kind': 'task_finish', 'entities': [tid, mid], 'value': None})

        # 2. Failures
        # Machines that fail at this time go down.
        failed_machines = sorted([mid for mid in machine_ids if machines_cfg[mid]['fails_at'] == t])
        for mid in failed_machines:
            machine_state[mid]['up'] = False
            # Each task running on such a machine stops (a fail event) and goes back to the queue.
            stopped_tasks = sorted(list(machine_state[mid]['tasks'].keys()))
            for tid in stopped_tasks:
                if tid in running_tasks:
                    del running_tasks[tid]
                queue.append(tid)
                outcomes_all.append({'time': t, 'kind': 'task_fail', 'entities': [tid, mid], 'value': None})
            machine_state[mid]['cpu_used'] = 0
            machine_state[mid]['mem_used'] = 0
            machine_state[mid]['tasks'] = {}

        # 3. Returns
        # Machines that return at this time come back, empty.
        returned_machines = sorted([mid for mid in machine_ids if machines_cfg[mid]['returns_at'] == t])
        for mid in returned_machines:
            machine_state[mid]['up'] = True

        # 4. Submissions
        # Tasks submitted at this time join the queue.
        submitted_tasks = sorted([s for s in submissions if s['time'] == t], key=lambda x: x['id'])
        for s in submitted_tasks:
            tid = s['id']
            tasks_info[tid] = s
            task_meta[tid] = {'submitted': s['time'], 'priority': s['priority']}
            queue.append(tid)

        # 5. Scheduling round
        # Higher priority first, then earlier submission time, then lower task id.
        queue.sort(key=lambda tid: (-task_meta[tid]['priority'], task_meta[tid]['submitted'], tid))

        reservation = None 
        round_queue = list(queue)
        i = 0
        while i < len(round_queue):
            tid = round_queue[i]
            if tid not in queue:
                i += 1
                continue

            t_req = tasks_info[tid]
            cpu_req, mem_req = t_req['cpu'], t_req['memory']
            started = False

            # a. First fit
            for mid in machine_ids:
                if not machine_state[mid]['up']: continue

                if reservation and mid == reservation[0]:
                    # Reservation and backfilling check
                    if (machine_state[mid]['cpu_used'] + cpu_req <= machines_cfg[mid]['cpu'] and 
                        machine_state[mid]['mem_used'] + mem_req <= machines_cfg[mid]['memory']):

                        finish_time = t + t_req['run_time']
                        t_res = reservation[1]
                        tid_res = reservation[2]

                        # Free CPU/Mem at t_res on reserved machine
                        cpu_at_res = machines_cfg[mid]['cpu']
                        mem_at_res = machines_cfg[mid]['memory']
                        for tid_run, start_t in machine_state[mid]['tasks'].items():
                            if start_t + tasks_info[tid_run]['run_time'] > t_res:
                                cpu_at_res -= tasks_info[tid_run]['cpu']
                                mem_at_res -= tasks_info[tid_run]['memory']

                        # Subtract reserved task's requests
                        cpu_at_res -= tasks_info[tid_res]['cpu']
                        mem_at_res -= tasks_info[tid_res]['memory']

                        if finish_time <= t_res or (cpu_at_res >= cpu_req and mem_at_res >= mem_req):
                            started = True
                else:
                    if (machine_state[mid]['cpu_used'] + cpu_req <= machines_cfg[mid]['cpu'] and 
                        machine_state[mid]['mem_used'] + mem_req <= machines_cfg[mid]['memory']):
                        started = True

                if started:
                    machine_state[mid]['cpu_used'] += cpu_req
                    machine_state[mid]['mem_used'] += mem_req
                    machine_state[mid]['tasks'][tid] = t
                    running_tasks[tid] = {'mid': mid, 'start_time': t, 'run_time': t_req['run_time']}
                    outcomes_all.append({'time': t, 'kind': 'task_start', 'entities': [tid, mid], 'value': None})
                    queue.remove(tid)
                    break

            if started:
                i += 1
                continue

            # b. Preemption (only for production tasks: priorities 9-11)
            if not started and task_meta[tid]['priority'] >= 9:
                for mid in machine_ids:
                    if not machine_state[mid]['up']: continue
                    # Free-tier tasks: priorities 0 and 1
                    free_tasks = [tid_f for tid_f in machine_state[mid]['tasks'] if task_meta[tid_f]['priority'] <= 1]
                    if not free_tasks: continue

                    # Order: lowest priority first, then most recently started first, then higher task id first
                    free_tasks.sort(key=lambda x: (task_meta[x]['priority'], -machine_state[mid]['tasks'][x], -int(x[1:])))

                    temp_cpu, temp_mem = machine_state[mid]['cpu_used'], machine_state[mid]['mem_used']
                    evicted_this_machine = []
                    for tid_ev in free_tasks:
                        if temp_cpu + cpu_req <= machines_cfg[mid]['cpu'] and temp_mem + mem_req <= machines_cfg[mid]['memory']:
                            break
                        temp_cpu -= tasks_info[tid_ev]['cpu']
                        temp_mem -= tasks_info[tid_ev]['memory']
                        evicted_this_machine.append(tid_ev)

                    if temp_cpu + cpu_req <= machines_cfg[mid]['cpu'] and temp_mem + mem_req <= machines_cfg[mid]['memory']:
                        for tid_ev in evicted_this_machine:
                            machine_state[mid]['cpu_used'] -= tasks_info[tid_ev]['cpu']
                            machine_state[mid]['mem_used'] -= tasks_info[tid_ev]['memory']
                            del machine_state[mid]['tasks'][tid_ev]
                            if tid_ev in running_tasks:
                                del running_tasks[tid_ev]
                            queue.append(tid_ev)
                            outcomes_all.append({'time': t, 'kind': 'task_evict', 'entities': [tid_ev, mid], 'value': None})

                        machine_state[mid]['cpu_used'] += cpu_req
                        machine_state[mid]['mem_used'] += mem_req
                        machine_state[mid]['tasks'][tid] = t
                        running_tasks[tid] = {'mid': mid, 'start_time': t, 'run_time': t_req['run_time']}
                        outcomes_all.append({'time': t, 'kind': 'task_start', 'entities': [tid, mid], 'value': None})
                        queue.remove(tid)
                        started = True
                        break

            if started:
                i += 1
                continue

            # c. Reservation
            if not started and reservation is None:
                best_t_res, best_mid_res = float('inf'), None
                for mid in machine_ids:
                    if not machine_state[mid]['up']:
                        ret_t = machines_cfg[mid]['returns_at']
                        if ret_t is not None and cpu_req <= machines_cfg[mid]['cpu'] and mem_req <= machines_cfg[mid]['memory']:
                            t_possible = ret_t
                        else: t_possible = float('inf')
                    else:
                        possible_times = sorted({t} | {start_t + tasks_info[tid_r]['run_time'] for tid_r, start_t in machine_state[mid]['tasks'].items()})
                        t_possible = float('inf')
                        for pt in possible_times:
                            if pt < t: continue
                            cpu_at_pt = machines_cfg[mid]['cpu']
                            mem_at_pt = machines_cfg[mid]['memory']
                            for tid_r, start_t in machine_state[mid]['tasks'].items():
                                if start_t + tasks_info[tid_r]['run_time'] > pt:
                                    cpu_at_pt -= tasks_info[tid_r]['cpu']
                                    mem_at_pt -= tasks_info[tid_r]['memory']
                            if cpu_at_pt >= cpu_req and mem_at_pt >= mem_req:
                                t_possible = pt
                                break
                    if t_possible < best_t_res:
                        best_t_res, best_mid_res = t_possible, mid

                if best_mid_res is not None:
                    reservation = (best_mid_res, best_t_res, tid)

            i += 1

    return [o for o in outcomes_all if o['time'] > start]
